query:
SELECT EXISTS (
    SELECT 1 FROM github_app_installation i
    WHERE i.id = $1 AND (
        (i.source_type = 'user' AND i.source_id = $2)
        OR (i.source_type = 'team' AND EXISTS (
            SELECT 1 FROM team_user t
            WHERE t.team_id::text = i.source_id AND t.user_id = $2
        ))
    )
) AS "claimed!"
